def link_assessments_to_transfers(apps, schema_editor):
    """把存量 AML 评估从账单/充值改挂到它们的 Transfer 上。

    规则（确定性、幂等，可重复执行）：
    - 账单评估取 invoice.transfer_id，充值评估取 deposit.transfer_id。
    - transfer 为一对一：同一 Transfer 若对应多条评估，按 checked_at 倒序（空值最后）、
      pk 倒序取最新一条挂上，其余保持 transfer 为空。
    - 账单已解绑 Transfer 的评估保持 transfer 为空；记录本身保留，付款地址、交易哈希与
      风险结果仍可在后台查看，不删除任何数据。
    - 已有 transfer 的行跳过，重复执行结果不变。
    """
    RiskAssessment = apps.get_model("aml", "RiskAssessment")

    claimed = set(
        RiskAssessment.objects.filter(transfer__isnull=False).values_list(
            "transfer_id", flat=True
        )
    )
    pending = (
        RiskAssessment.objects.filter(transfer__isnull=True)
        .select_related("invoice", "deposit")
        .order_by(F("checked_at").desc(nulls_last=True), "-pk")
    )
    for assessment in pending.iterator():
        if assessment.invoice_id:
            transfer_id = assessment.invoice.transfer_id
        elif assessment.deposit_id:
            transfer_id = assessment.deposit.transfer_id
        else:
            transfer_id = None
        if transfer_id is None or transfer_id in claimed:
            continue
        assessment.transfer_id = transfer_id
        assessment.save(update_fields=["transfer"])
        claimed.add(transfer_id)


